'use client'; import Link from 'next/link';
import { useState } from 'react';
import { Fingerprint, Lock, ShieldCheck } from 'lucide-react'; import { VendorModuleHeader } from '@/components/vendor/ui/VendorModuleHeader';
import { VENDOR_PORTAL_ROUTES } from '@/lib/vendor/navigation';
import { useVendorAppStore } from '@/lib/vendor/store/vendor-app-store'; export function VendorLoginWorkspace() { const [step, setStep] = useState<'login' | 'mfa' | 'register'>('login'); const mfaEnabled = useVendorAppStore((s) => s.mfaEnabled); const setMfa = useVendorAppStore((s) => s.setMfaEnabled); const setBiometric = useVendorAppStore((s) => s.setBiometricEnabled); return ( <div className="flex min-h-screen items-center justify-center bg-slate-950 px-4 py-12"> <div className="w-full max-w-md space-y-6 rounded-2xl border border-slate-800 bg-slate-900 p-8 shadow-2xl"> <VendorModuleHeader title="Nexora Vendor Access" description="Secure login · GST-verified onboarding · MFA · session management." /> {step === 'register' ? ( <form className="space-y-3" onSubmit={(e) => e.preventDefault()}> <input className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" placeholder="Legal business name" /> <input className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" placeholder="GSTIN (auto-verify)" /> <button type="submit" className="w-full rounded-lg bg-vendor-primary py-2.5 text-sm font-bold text-white"> Submit for verification </button> <p className="text-center text-[10px] text-vendor-muted">GSTIN validated against GSTN sandbox · audit logged</p> <button type="button" onClick={() => setStep('login')} className="w-full text-xs font-bold text-vendor-primary" > Back to login </button> </form> ) : ( <form className="space-y-3" onSubmit={(e) => { e.preventDefault(); if (mfaEnabled && step === 'login') setStep('mfa'); }} > <input type="email" className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" placeholder="Work email" /> <input type="password" className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" placeholder="Password" /> {step === 'mfa' ? ( <input className="w-full rounded-lg border border-slate-700 bg-slate-950 px-3 py-2 text-sm text-white" placeholder="6-digit MFA code" /> ) : null} <Link href={VENDOR_PORTAL_ROUTES.dashboard} className="flex w-full items-center justify-center gap-2 rounded-lg bg-vendor-primary py-2.5 text-sm font-bold text-white hover:opacity-90" > <Lock className="h-4 w-4" aria-hidden /> {step === 'mfa' ? 'Verify & enter portal' : 'Continue'} </Link> </form> )} <div className="space-y-2 border-t border-slate-800 pt-4 text-xs text-slate-400"> <label className="flex items-center gap-2"> <input type="checkbox" checked={mfaEnabled} onChange={(e) => setMfa(e.target.checked)} /> <ShieldCheck className="h-3.5 w-3.5" aria-hidden /> Require MFA on this device </label> <label className="flex items-center gap-2"> <input type="checkbox" onChange={(e) => setBiometric(e.target.checked)} /> <Fingerprint className="h-3.5 w-3.5" aria-hidden /> Enable biometric unlock (WebAuthn placeholder) </label> <button type="button" onClick={() => setStep('register')} className="font-bold text-vendor-primary hover:underline" > Self-service vendor registration </button> </div> </div> </div> );
}
